package com.supermercado.pos.ui;

import javax.swing.*;import com.supermercado.pos.dao.*;import com.supermercado.pos.servicio.*;
public class ProductosFrame extends JFrame {public ProductosFrame(){super("Catálogo de productos");UI.permiso("CATALOGO_ADMIN");JPanel p=UI.panel();JTextField codigo=UI.campo(p,"Código de barras");JTextField nombre=UI.campo(p,"Nombre");JTextField precio=UI.campo(p,"Precio Q");JTextField stock=UI.campo(p,"Stock");JButton b=new JButton("Agregar producto");JButton ver=new JButton("Ver productos");p.add(b);p.add(ver);b.addActionListener(e->UI.accion(this,()->{Operaciones.tx(c->{Sql.ejecutar(c,"INSERT INTO producto(codigo_barras,nombre,precio,stock) VALUES(?,?,?,?)",codigo.getText(),nombre.getText(),Operaciones.dinero(precio.getText()),Integer.parseInt(stock.getText()));return null;});UI.mensaje(this,"Producto agregado");}));ver.addActionListener(e->UI.mostrar("Productos","SELECT id,codigo_barras,nombre,precio,stock FROM producto ORDER BY id"));add(p);pack();setLocationRelativeTo(null);}}